pub struct Document {              // the Whole
    parts: Vec<Paragraph>,         // owned parts: dropped with the document
    backing: File,                 // owned resource: closed on drop
}
impl Document {
    pub fn add(&mut self, text: &str) { self.parts.push(Paragraph::new(text)); }
    pub fn total_len(&self) -> usize { self.parts.iter().map(Paragraph::len).sum() }
}

