pub struct Document { parts: RefCell<Vec<Rc<Paragraph>>> }     // owns its parts
pub struct Paragraph { text: String, parent: RefCell<Weak<Document>> }
fn owner_summary(p: &Paragraph) -> Option<String> {
    let doc = p.parent.borrow().upgrade()?;   // None once the whole has been dropped
    Some(format!("{} parts", doc.parts.borrow().len()))
}

pub struct Document { nodes: Vec<Node>, root: NodeId }      // the Whole owns everything
pub struct Node { parent: Option<NodeId>, children: Vec<NodeId>, text: String }
impl Document {
    pub fn add_child(&mut self, parent: NodeId, text: String) -> NodeId {
        let id = NodeId(self.nodes.len() as u32);
        self.nodes.push(Node { parent: Some(parent), children: Vec::new(), text });
        self.nodes[parent.0 as usize].children.push(id);    // link as an index
        id
    }
}
